/**
 * 比較表・早見表。
 *
 * 本文はプレーンテキストとして描画されるため、本文に Markdown の表を書いても
 * 記号のまま出る。検索エンジンや AI に表として読ませるには本物の table 要素が
 * 要るので、データとして持たせて描画側で組み立てる。
 */
type GuideTable = {
  caption?: string;
  headers: string[];
  rows: string[][];
};

type GuideSection = { heading: string; body: string; table?: GuideTable };
type FAQ = { q: string; a: string };

type Guide = {
  title: string;
  description: string;
  image?: string;
  /** 画像の内容を説明する alt。未指定ならタイトルを使う。 */
  imageAlt?: string;
  datePublished: string;
  dateModified: string;
  /**
   * 商品検索に使う語。記事末尾の購入リンク（ShopCTA）がこれで検索する。
   * **検索・AI検索で狙う語（targetQuery）とは別物。** 商品が出てくる語を書く。
   */
  searchKeyword?: string;
  /**
   * 検索・AI検索で狙う語。
   *
   * searchKeyword と分けている。昆布締めの個別記事は商品検索の都合で
   * 「真昆布」「羅臼昆布」を searchKeyword にしているが、その語で記事の出来を
   * 測ると実態と合わない（AI引用チェックが商品名で測っていた）。
   * meta の生成と引用チェックはこちらを使う。
   */
  targetQuery?: string;
  /**
   * 記事末尾に出す関連記事の slug。話題の近いものを3〜4本選ぶ。
   * 柱記事は配下の個別記事をすべて並べ、個別記事は柱を必ず含める。
   * どの記事の related にも入らない孤立記事は site-check.ts が warn で出す。
   *
   * 未指定だと GUIDES の先頭から順に埋められる。記事が増えると、どの記事を
   * 開いても同じ4本が並ぶだけになり、内部リンクとして働かない。新しい記事を
   * 足すときは必ず書く（site-check.ts が未指定を warn で出す）。
   */
  related?: string[];
  /**
   * 作り方の記事に付ける Recipe の構造化データ。
   *
   * **ページに材料と手順が見えている記事にだけ付ける。** 構造化データと本文が
   * 食い違うと、検索側に不正扱いされる。分量を本文に書いていない記事
   * （出典のレシピの分量を写さない方針で書いたもの）には付けない。
   *
   * 時間は出典に書かれているものだけを入れる。書かれていないものは省く。
   * 見栄えのために推測の時間を入れない。
   */
  recipe?: {
    name: string;
    /** Recipe の recipeCategory。省略時は「だし」 */
    category?: string;
    /** 出来上がり量。出典に記載がなければ省く */
    recipeYield?: string;
    /** ISO 8601 の期間。例: PT30M, PT3H */
    prepTime?: string;
    cookTime?: string;
    totalTime?: string;
    ingredients: string[];
    steps: { name: string; text: string }[];
  };
  sections: GuideSection[];
  faq?: FAQ[];
};

