        body: "日本昆布協会の湯豆腐のレシピ（昆布大使 菊間恵子さん）では、水（軟水）1Lに昆布10〜15gを入れて「1晩（10時間位）冷蔵庫で寝かせ」た昆布水を使います。鍋には昆布水で使った昆布を敷き、昆布水を注いで塩を少々入れ、火にかけます。煮立ってきたら豆腐を入れて静かに煮ます。\n\n昆布だしの基本の取り方では、昆布は沸騰直前に取り出します。湯豆腐のこのレシピでは、昆布を鍋に敷いたまま煮立てています。同じ昆布でも、だしを取るときと湯豆腐にするときで、資料の扱いが違います。\n\n昆布水に向く昆布として、このレシピは「利尻昆布、羅臼昆布、真昆布がおすすめです」としています。北海道の資料は、リシリコンブ（利尻昆布）の用途に「湯豆腐」を挙げています。\n\n出典: 日本昆布協会「湯豆腐～とろろ昆布入り～」 https://kombu.or.jp/recipe/2179 ／ 北海道 水産林務部「リシリコンブ（利尻昆布）」 https://www.pref.hokkaido.lg.jp/sr/gid/fis091.html",
