        heading: "昆布を取り出すか、入れたままか（だしの取り方と湯豆腐・鍋の違い）",
        body: "昆布を沸騰直前に取り出すのは、だしを取るときの手順です。日本昆布協会の「昆布だしの取り方」は、水1Lに昆布10g〜20g程度を30分漬けて中火にかけ、沸騰直前に取り出すとしています。鳥取県の資料（鳥取短期大学の協力）も、こんぶだしは沸騰直前（90〜95℃）で取り出すとしています。\n\n一方、日本昆布協会のレシピのうち、湯豆腐（とろろ昆布入り）は昆布を鍋に敷いたまま煮立てます。マグロとネギの小鍋仕立ては、鍋に水と昆布を入れて火にかけ、調味料と具を加えてひと煮立ちさせる手順で、昆布を取り出す記載はありません。\n\n湯豆腐や鍋は、だしを別に取るのではなく、昆布の入った鍋でそのまま具を煮る料理として書かれています。煮立てた昆布の味がどう変わるかを比べた資料は、このサイトでは確かめられていません。だしだけを澄んだ味で取りたいときは、だしの取り方の手順に従い、昆布を取り出してから豆腐を入れる方法もあります。\n\n出典: 日本昆布協会「昆布だしの取り方」 https://kombu.or.jp/power/dashi ／ 鳥取県「出汁の取り方」 https://www.pref.tottori.lg.jp/224613.htm ／ 日本昆布協会「湯豆腐～とろろ昆布入り～」 https://kombu.or.jp/recipe/2179 ／ 日本昆布協会「長ネギとマグロの小鍋仕立て～昆布だし～」 https://kombu.or.jp/recipe/2190",
