        heading: "鍋の大きさで昆布の量を決める",
        body: "協会の湯豆腐のレシピは2人分で、昆布水は「お鍋の2/3位まで」注ぐとしています。昆布水は水1Lに昆布10〜15gなので、鍋に入る水の量に合わせて昆布の量を変えれば、同じ割合になります。\n\n次の計算は、協会の割合（水1Lに10〜15g）を水の量に当てはめた当サイトの計算例です。資料に鍋の大きさごとの量が書かれているわけではありません。\n\nもっと少ない量では、協会の小鍋仕立てのレシピが水150ccに昆布2〜3cm角1枚です。一人用の小鍋なら、この量が目安になります。\n\n昆布水そのものの作り方と保存は、昆布水の作り方の記事にまとめています。協会の別の資料の昆布水（水1.5Lに昆布20g程度、3時間以上）は「冷蔵庫で1週間くらいはもちます」とされているので、鍋の季節は多めに作っておく使い方もできます。\n\n出典: 日本昆布協会「湯豆腐～とろろ昆布入り～」 https://kombu.or.jp/recipe/2179 ／ 日本昆布協会「長ネギとマグロの小鍋仕立て～昆布だし～」 https://kombu.or.jp/recipe/2190 ／ 日本昆布協会「『昆布水』で簡単昆布だし」 https://kombu.or.jp/power/dashi2",
