        body: "農林水産省「和ごはん」が紹介する年越しそばのつゆ（取材協力: 小松庵総本家）は、出汁を「水1ℓに対し、カツオとサバの混合削り節を50g」で取ります。昆布は材料に入っていません。そばつゆは、昆布を使わなくても成り立つつゆです。\n\n一方で、昆布と鰹節を合わせることについて、農林水産省の別の資料は「昆布に含まれるグルタミン酸と鰹節に含まれるイノシン酸の二つが合わさる事で、相乗効果となり、だしのうま味を引き立たせます」としています。\n\n出典にはそばつゆに昆布を使う記載は無く、ここからは当サイトの提案です。昆布を足すなら、日本昆布協会の基本の昆布だし（水1Lに昆布10g〜20g程度）の量を、そのまま削り節の出汁の水1Lに当てはめるのが始めやすい量です。昆布を水に30分くらい漬けて火にかけ、沸騰直前に取り出してから、削り節を入れます。\n\n出典: 農林水産省「和ごはん」お蕎麦を知って美味しい年越しそばを食べよう！ https://www.maff.go.jp/j/keikaku/syokubunka/culture/wagohan/articles/2212/spe12_02.html ／ 農林水産省「和食ワールドチャレンジ」だし・うま味について https://www.maff.go.jp/j/yusyutu_kokusai/washoku-world-challenge/learning_03.html ／ 日本昆布協会「昆布だしの取り方」 https://kombu.or.jp/power/dashi",
