        body: "農林水産省「和ごはん」の年越しそばのページでは、つゆを出汁とかえしに分けて作ります。\n\n出汁は、水1Lに対してカツオとサバの混合削り節を50g使います。湯がグラグラ煮立ったら弱火にして削り節を入れ、弱火で15〜20分煮出します。こすときは「絶対に絞らないこと」とされています。\n\nかえしは、しょうゆ5：砂糖1：本みりん1が基本です。5人分は、しょうゆ100ccを弱火で温め、砂糖と本みりんを中さじ2ずつ加えて約5分加熱します。\n\nかえしと出汁の割合は、冷たいそばが「かえし1：出汁3」、温かいそばが「かえし1：出汁7」が基準とされています。\n\n年越しそばそのものは、江戸時代に始まった習慣で、もとは大みそかの夜の祝膳の一つだったとされています。食べる時間は決まっていませんが、年が変わる前に食べ終えるよう勧められています。\n\nこのページの材料に昆布はありません。「昆布を足す」話は、ここから先の資料と当サイトの提案になります。\n\n出典: 農林水産省「和ごはん」お蕎麦を知って美味しい年越しそばを食べよう！ https://www.maff.go.jp/j/keikaku/syokubunka/culture/wagohan/articles/2212/spe12_02.html",
