        body: "昆布だしにはヨウ素が多く含まれています。文部科学省「日本食品標準成分表（八訂）増補2023年」では、100gあたり、昆布だし（水出し）が5,300μg、荒節・昆布だし（合わせだし）が1,500μgです。成分表の値は一つの目安で、家庭で取るだしの値と同じとは限りません。この記事の提案のように削り節の出汁に昆布を足したつゆの値は、成分表には載っていません。\n\n厚生労働省「日本人の食事摂取基準（2025年版）」では、ヨウ素の耐容上限量を成人3,000μg/日、妊婦・授乳婦2,000μg/日としています。同じ資料では、上限は習慣的にとる量に当てはめるもので、成人の場合、昆布を使った献立による高い摂取は「連日でない限り問題はない」とされています。一方で、昆布だしや昆布を使った料理を毎日続けてたくさんとると、とりすぎになることがあります。年末年始は昆布巻きなど昆布を使う料理が続きやすい時期です。甲状腺の病気で治療中の方や、妊娠中・授乳中の方は、医師に相談してください。昆布そのものの成分は昆布の栄養成分の記事にまとめています。\n\n出典: 文部科学省「食品成分データベース」昆布だし 水出し（17020） https://fooddb.mext.go.jp/details/details.pl?ITEM_NO=17_17020_7 ／ 荒節・昆布だし（17021） https://fooddb.mext.go.jp/details/details.pl?ITEM_NO=17_17021_7 ／ 厚生労働省「日本人の食事摂取基準（2025年版）」 https://www.mhlw.go.jp/content/10904750/001316469.pdf",
