        body: "朝にだしを取る手間を省くなら、前の晩に昆布水を作っておく方法があります。日本昆布協会の昆布水は、水1.5Lに昆布20g程度を入れて3時間以上（できれば1晩）おくもので、「冷蔵庫で1週間くらいはもちます」とされています。\n\n1月6日の夜に昆布水を仕込んでおけば、7日の朝はその昆布水を鍋に取り、かつおを使うなら沸騰させてからけずりかつおを入れて、鳥取県の資料の手順（約1分加熱し、火を止めて2〜3分おく）でこします。昆布だけでよければ、昆布水をそのまま使えます。昆布水は七草がゆに使う600mLより多くできるので、残りは冷蔵庫に入れて、ほかの料理に回せます。\n\n鳥取県の資料でも、こんぶの水だしは夏30〜60分・冬2〜3時間浸すとしています。冬は浸す時間を長めに取る、という点で協会の「3時間以上」と方向は同じです。昆布水の作り方と使い方は、昆布水の作り方の記事にまとめています。\n\n出典: 日本昆布協会「『昆布水』で簡単昆布だし」 https://kombu.or.jp/power/dashi2",
