        body: "真昆布の用途は幅広く、資料によって挙げ方が少しずつ違います。北海道の資料は高級だし昆布のほか、塩昆布や佃煮・角煮などの加工品を挙げ、春先のやわらかい若い昆布は海藻サラダや昆布巻きに使われるとしています。北海道ぎょれんは「だし、塩昆布、おぼろ・とろろ昆布、佃煮、バッテラ等」です。\n\n昆布締めにも使われています。日本昆布協会の鶏むね肉の昆布締めのレシピは真昆布を使い、農林水産省「うちの郷土料理」の富山県の昆布〆（バイ貝）でも真昆布が勧められています。\n\nだしの取り方は、ほかの昆布と同じです。日本昆布協会の取り方は、水1Lに昆布10g〜20g程度を30分漬け、中火にかけて沸騰直前に取り出す方法です。手順は昆布だしの取り方の記事にまとめています。\n\n出典: 北海道 水産林務部「マコンブ（真昆布）」 / 北海道ぎょれん「北海道のこんぶ」 / 日本昆布協会「鶏むね肉の昆布締め」 https://kombu.or.jp/recipe/2142 / 農林水産省「うちの郷土料理」昆布〆 富山県 https://www.maff.go.jp/j/keikaku/syokubunka/k_ryouri/search_menu/menu/37_12_toyama.html / 日本昆布協会「昆布だしの取り方」 https://kombu.or.jp/power/dashi",
