        body: "文部科学省の日本食品標準成分表には「えながおにこんぶ 素干し」（食品番号09013）が載っています。北海道の資料では、羅臼町産のオニコンブは検査規格上「りしり系えながおにこんぶ」として出荷されるとされており、成分表の食品名と同じ「えながおにこんぶ」の名が出てきます。\n\n真昆布（まこんぶ）と並べると、カリウムとたんぱく質が多く、食物繊維総量は少ない値です。\n\n**ヨウ素の値は、えながおにこんぶには載っていません（表で「-」）。** 値が無いことは「少ない」という意味ではありません。昆布として、ヨウ素を多く含む前提で扱ってください。\n\n出典: 文部科学省「食品成分データベース」えながおにこんぶ 素干し（09013） https://fooddb.mext.go.jp/details/details.pl?ITEM_NO=9_09013_7 ／ まこんぶ 素干し 乾（09017） https://fooddb.mext.go.jp/details/details.pl?ITEM_NO=9_09017_7",
