        body: "昆布はヨウ素を多く含む食品です。成分表でヨウ素の値があるまこんぶは、素干し1gで約2,000μgです。羅臼昆布はおしゃぶり昆布やおやつ昆布のように昆布そのものを食べる加工品にもなるため、だしに使う場合より口に入る昆布の量が増えることがあります。\n\n厚生労働省「日本人の食事摂取基準（2025年版）」は、ヨウ素の耐容上限量を成人で3,000μg/日、妊婦・授乳婦で2,000μg/日と定めています。同じ資料では、上限は習慣的にとる量に当てはめるもので、成人の場合、昆布を使った献立による高い摂取は「連日でない限り問題はない」とされています。昆布を大量に、毎日続けて食べることは避けてください。\n\n甲状腺の病気で治療中の方、妊娠中・授乳中の方は、医師に相談してください。成分の詳細は昆布の栄養成分の記事にまとめています。\n\n出典: 厚生労働省「日本人の食事摂取基準（2025年版）」 https://www.mhlw.go.jp/content/10904750/001316469.pdf",
