        heading: "結論: もどした昆布で巻き、やわらかく煮てから味を入れる",
        body: "昆布巻きは、水でもどした昆布で鮭や身欠きニシンを巻き、かんぴょうで結んで煮る料理です。農林水産省の資料は北海道の昆布巻きの作り方を、昆布とかんぴょうを水でもどし、魚を昆布で巻いてかんぴょうで縛り、砂糖・しょうゆ・酒で煮る、と記しています。\n\n日本昆布協会の鮭とごぼうのレシピ（4人分）では、日高昆布を使い、あくを取りながら中火で約50分煮て、竹串がすっと通ったら調味料を加えて落としぶたで約30分煮ます。先にやわらかくしてから味を入れる二段階です。\n\n失敗しないコツは、出典に書かれている3つです。昆布の繊維と平行に巻く、煮ると膨らむのできつく結ばない、竹串がすっと通ってから調味料を入れる。手早く作りたいなら、薄切りの豚肉を巻く協会のレシピがあり、煮る時間は10分くらいです（下の「簡単に作るなら」の節）。\n\n正月によく食べられ、「養老昆布」の当て字から不老長寿、「子生（こぶ）」から子孫繁栄の縁起担ぎとされています（農林水産省）。",
