        body: "出典に書かれている注意は、「昆布が硬いまま」「かんぴょうが食い込む」「厚さが片寄って食べにくい」を避けるためのものです。どの失敗が多いかを調べた資料は見つけられなかったため、出典の注意を並べています。\n\n巻く向き。協会のレシピは、昆布の繊維と平行の向きに巻くよう勧めています。厚い部分と薄い部分が片寄らず、食べやすくなるためです。\n\n結び方。農林水産省の資料は、昆布は煮ると膨らむため、きつく結びすぎないようにするとしています。かんぴょうできつく縛ると、煮ているあいだに食い込みます。\n\n酢。協会のレシピは、煮るときに酢を加えると昆布がやわらかく煮えるとしています。富山の昆布巻きのレシピ（農林水産省「うちの郷土料理」）でも、水から煮て酢を少し加えています。\n\n味付けは、やわらかくなってから入れます。協会の鮭のレシピも富山のレシピも、先に昆布をやわらかくしてから調味料を加える順番です。富山のレシピでは調味料を半量ずつ2回に分けて加えています。早煮昆布を使う協会のレシピは、調味料を入れたあと「絶対に煮立てないこと」としています。\n\n出典: 日本昆布協会「憧れの昆布巻き ～まずは鮭＆ごぼう編～」 https://kombu.or.jp/recipe/2125 / 同「あっさり鮭昆布巻き」 https://kombu.or.jp/recipe/2430 / 農林水産省「にっぽん伝統食図鑑」昆布巻き https://www.maff.go.jp/j/keikaku/syokubunka/traditional-foods/menu/kombumaki.html",
