        body: "文部科学省「日本食品標準成分表（八訂）増補2023年」には、昆布だし（水出し）、かつおだし（荒節）、荒節・昆布だし（合わせだし）の値が載っています。どれも100gあたりのエネルギーは2〜4kcalで、たんぱく質も1g未満と、だしそのものから多くはとれません。\n\nいちばん差が大きいのはヨウ素です。100gあたり、昆布だし（水出し）は5,300μg、荒節・昆布だしは1,500μg、かつおだし（荒節）は1μgです。カリウムも昆布だしが140mgと、かつおだしの29mgより多くなっています。\n\n成分表の値は一つの目安で、家庭で取るだしの値と同じとは限りません。\n\n昆布だしはヨウ素が多いだしです。厚生労働省「日本人の食事摂取基準（2025年版）」ではヨウ素の耐容上限量を成人3,000μg/日、妊婦・授乳婦2,000μg/日と定めており、昆布だしや昆布を使った料理を毎日続けてたくさんとると、とりすぎになることがあります。甲状腺の病気で治療中の方や、妊娠中・授乳中の方は、医師に相談してください。昆布そのものの成分は昆布の栄養成分の記事にまとめています。\n\n出典: 文部科学省「食品成分データベース」昆布だし 水出し（17020） https://fooddb.mext.go.jp/details/details.pl?ITEM_NO=17_17020_7 ／ かつおだし 荒節（17019） https://fooddb.mext.go.jp/details/details.pl?ITEM_NO=17_17019_7 ／ 荒節・昆布だし（17021） https://fooddb.mext.go.jp/details/details.pl?ITEM_NO=17_17021_7",
