        body: "昆布締めは、料理の解説記事で「昆布が素材の余分な水分を吸収することで身が締まり、さらに昆布の旨みが素材に移る」調理法と説明されています。昆布のうま味の正体は、日本昆布協会によるとグルタミン酸です。\n\nサーモン（鮭）の昆布締めの特徴は、柵のまま締める鯛やヒラメと違い、先に切ってから挟む点です。切ったものは柵より早く締まり、協会の鯛のレシピも「切り身を使う場合は昆布に巻く時間を短くします。」としています。もう一つは香りで、協会のサーモンのレシピは昆布に白ワインを振って「かおりをつけます」。\n\nサーモンでどれだけ水分が抜けるか、うま味がどれだけ移るかを測った資料は、当サイトでは確認できていません。\n\n出典: サライ.jp「自宅で「平目の昆布締め」を作るコツ【プロ直伝の技とコツ】」 https://serai.jp/gourmet/348469 ／ 日本昆布協会「だし・うま味について」 https://kombu.or.jp/power/dashiumami",
