        body: "ヒラメを昆布で締める目的は、水分を抜くことと、昆布のうま味を移すことです。平目の昆布締めを寿司職人に聞いた記事では、昆布締めを「昆布が素材の余分な水分を吸収することで身が締まり、さらに昆布の旨みが素材に移るという、保存性と美味しさを高める調理法」と説明しています。\n\nもとは保存のための方法でした。農林水産省の資料によると、昆布〆は江戸時代に北前船が運んだ北海道の昆布と富山湾の魚を組み合わせて生まれ、「冷蔵庫がなかった当時、生魚を保存する手段として昆布に挟んで余分な水分を吸収する方法が考案された」ものです。その後、「昆布の旨味の染み込んだ魚は味わい深く、身は熟成され程よい弾力が生まれる」ことから広く定着したとされています。昆布のうま味の正体は、日本昆布協会によるとグルタミン酸です。\n\nいまは冷蔵庫があるので、家庭で作る目的は保存より味と食感のほうです。日持ちが延びることを示した資料は確認できていないため、作ったら早めに食べきってください。ヒラメでどれだけ水分が抜けるかを測った資料も、当サイトでは確認できていません。\n\n出典: サライ.jp「自宅で「平目の昆布締め」を作るコツ【プロ直伝の技とコツ】」 https://serai.jp/gourmet/348469 ／ 農林水産省「にっぽん伝統食図鑑」昆布〆 https://www.maff.go.jp/j/keikaku/syokubunka/traditional-foods/menu/kobu_zime.html ／ 日本昆布協会「だし・うま味について」 https://kombu.or.jp/power/dashiumami",
