        body: "数値だけを見ると、昆布を使った料理は簡単に上限を超えます。成分表の値から計算すると、まこんぶ（素干し）は1gで約2,000μg、昆布だし（水出し）は100gで5,300μgのヨウ素を含むためです。\n\nこの点について、同じ資料には次の記載があります。\n\n「耐容上限量は、習慣的なヨウ素摂取に適用されるものである。昆布等の海藻類を用いた献立の摂取は 3 mg/日を超えるヨウ素の摂取を生じるが、吸収された昆布由来のヨウ素は 2 日以内に尿に完全に排泄される。したがって、成人の場合、昆布等の海藻類を用いた献立を摂取することに起因する耐容上限量を超える高ヨウ素摂取は、連日でない限り問題はない。」\n\nつまり、上限と比べるのは「その日に食べた量」ではなく「習慣的にとっている量」です。昆布を使った食事が続く日があること自体は、資料の上では問題とされていません。\n\n一方で、妊婦と授乳婦は扱いが別です。「胎児のヨウ素高曝露と高濃度母乳の分泌を避けるため、高摂取の頻度を一般成人よりも少なくする必要がある」とされています。\n\n出典: 厚生労働省「日本人の食事摂取基準（2025年版）」 p.318 https://www.mhlw.go.jp/content/10904750/001316469.pdf",
