    description: "塩昆布の食塩相当量は100gあたり18.0gで、素干しのまこんぶ（6.6g）の3倍近くあります（日本食品標準成分表）。塩ふき昆布との違いを資料で確かめられる範囲で整理し、2人分のおかずに5〜6gという協会レシピの量、1人分の塩分の計算例、ヨウ素の注意と保存もまとめました。",
