        body: "日本昆布協会の加工品の一覧では、「塩昆布」と「乾燥塩吹き昆布」が別の品目として挙げられています。見た目も使い方も近いですが、製品の区分としては分かれています。一覧の26種は、昆布の加工品一覧の記事に並べています。\n\nどちらも昆布そのものを食べるものなので、だし用の昆布より塩分が高くなります。日本食品標準成分表（八訂）増補2023年では、塩昆布の食塩相当量は100gあたり18.0gです。素干しのまこんぶは6.6gなので、3倍近くあります。\n\n少量で味が決まるぶん、入れすぎると塩辛くなります。",
