        body: "乾燥昆布は、湿気を避けて乾燥した場所に置くのが基本です。日本昆布協会は「湿気をさけ、乾燥したところに保存すれば大丈夫。冷蔵庫か冷凍庫に入れておくのも良いでしょう」としています。\n\n置き場所ごとに答えると、次のとおりです。\n\n常温: 湿気を避けた乾燥した場所なら大丈夫です（日本昆布協会）。\n\n冷蔵・冷凍: 入れても良いとされています（日本昆布協会）。冷蔵でなければいけない、という記載はありません。\n\n開封後: 15cmくらいの長さに切って、缶や瓶に入れておくと使いやすい、とされています（日本昆布協会）。\n\nどのくらいもつか: 乾燥昆布の期限を示した記載は、確認した協会のページ（保存方法・よくある質問）にはありませんでした。袋の表示を見てください。\n\n昆布の状態ごとに、置き場所と入れ方をまとめました。",
