        body: "昆布をそのまま食べるおやつは、おしゃぶり昆布・都こんぶ・酢昆布・おつまみ昆布の4つに分けると選びやすくなります。どれも昆布の加工品で、日本昆布協会の加工品の一覧（26種）にはおしゃぶり昆布・酢昆布・おやつ昆布などが挙げられています。\n\n選ぶときは、味（梅・プレーン・酢など）と食感（しっかり噛む・柔らかめ）で絞り、袋の原材料・内容量・栄養成分表示を見ます。\n\n**気をつけることは塩分とヨウ素です。** 成分表では、塩昆布（09022）の食塩相当量が100gあたり18.0g、まこんぶ（素干し・乾 09017）のヨウ素が100gあたり200,000μg（1gで約2,000μg）です。おやつ用の加工品そのものの値は成分表で確かめられていません。詳しくはヨウ素の節にまとめています。\n\n**このページでは「おすすめ」の順位を付けていません。** 売れ行きや食べ比べの資料が無いためです。\n\n出典: 日本昆布協会「こんぶネット」 昆布の種類 https://kombu.or.jp/power/shurui / 文部科学省「食品成分データベース」まこんぶ 素干し 乾（09017） https://fooddb.mext.go.jp/details/details.pl?ITEM_NO=9_09017_7",
