        body: "都こんぶは、中野物産が作っている酢こんぶです。製造元の公式サイトの酢こんぶのページには、15g 都こんぶ・15g 都こんぶ 梅酢・15g 都パック・45g / 70g / 130g の都こんぶピロー・25g 粉だく200%都こんぶの7品が載っています（2026年11月9日に確認）。\n\n味で分かれるのは、梅酢と、白い粉を増やした粉だく200%です。ほかは内容量と包装の違いです。\n\n原料は、公式サイトによると「北海道・道南地方や三陸地方の真昆布」で、「およそ11の行程を経て作られています」。\n\n昆布にはヨウ素が含まれます。都こんぶのヨウ素の値は成分表で確かめられていないので、量は控えめにしてください（ヨウ素の節にまとめています）。\n\n**このページに価格は書いていません。** 価格は変わるため、商品ページ（取得した時点の参考価格）で確認してください。\n\n出典: 中野物産「酢こんぶ」 https://www.nakanobussan.co.jp/products/miyako/ / 中野物産「手間をかけて作る酢こんぶ」 https://www.nakanobussan.co.jp/about/index.html",
