        body: "昆布にはヨウ素が含まれます。日本人の食事摂取基準（2025年版）では、ヨウ素の耐容上限量は成人3,000μg/日、妊婦・授乳婦2,000μg/日とされています。子どもの上限は、成人の上限を体重あたりに直した値に年齢ごとの体重を掛けて決められており、体が小さいほど小さくなります。\n\n都こんぶのヨウ素の値は、成分表で確かめられていません。原料と同じ真昆布の素干し（まこんぶ 素干し・乾 09017）は100gあたり200,000μg、1gで約2,000μgです。酢に漬けて加工したものが同じ値とは限りませんが、少量でも上限を超えうる食品として扱ってください。\n\n同じ資料には、耐容上限量は「習慣的なヨウ素摂取に適用されるものである」、昆布等の海藻類を用いた献立による高ヨウ素摂取は「連日でない限り問題はない」とも書かれています。**このサイトでは、1日に何箱という目安は示していません。** 毎日続けて食べることは避けてください。甲状腺の病気で治療中の方、妊娠中・授乳中の方は医師に相談してください。詳しくは昆布の栄養成分の記事にまとめています。\n\n出典: 厚生労働省「日本人の食事摂取基準（2025年版）」 pp.316-318 https://www.mhlw.go.jp/content/10904750/001316469.pdf / 文部科学省「食品成分データベース」まこんぶ 素干し 乾（09017） https://fooddb.mext.go.jp/details/details.pl?ITEM_NO=9_09017_7",
